import { sanitizeAIError, type SanitizedAIError } from "@/lib/ai/shared/errors";

const PREFIX = "switchy-ai-error:";

export function serializeWorkError(error: unknown): string {
  return PREFIX + JSON.stringify(sanitizeAIError(error));
}

export function deserializeWorkError(value: string): SanitizedAIError {
  if (value.startsWith(PREFIX)) {
    try {
      const parsed = JSON.parse(value.slice(PREFIX.length)) as SanitizedAIError;
      // Only accept the exact safe representation generated by this module.
      if (typeof parsed.code === "string" && typeof parsed.message === "string") {
        return { code: parsed.code, message: parsed.message };
      }
    } catch { /* Legacy string errors are sanitized below. */ }
  }
  return sanitizeAIError(new Error(value));
}
